(()=>{'use strict';
const $=id=>document.getElementById(id),fmt=n=>Number.isFinite(n)?n.toLocaleString('ko-KR',{maximumFractionDigits:1}):'—';
const compact=n=>{for(const [unit,label] of [[1e16,'경'],[1e12,'조'],[1e8,'억'],[1e4,'만']])if(n>=unit)return (n/unit).toLocaleString('ko-KR',{maximumFractionDigits:1})+label;return fmt(n);};
let worker=null,timer=null,url=null,imageToken=0,runToken=0,pendingReject=null,dict={};
const status=text=>$('status').textContent=text;
function clearImage(){imageToken++;$('preview').hidden=true;$('preview').removeAttribute('src');if(url)URL.revokeObjectURL(url);url=null;$('capture').value='';}
function stop(message='중지했습니다. 이미지와 결과 메모리를 비웠습니다.') {runToken++;clearTimeout(timer);pendingReject?.(Error('중지'));pendingReject=null;worker?.terminate();worker=null;clearImage();$('results').replaceChildren();$('overlay').textContent='모바일 도우미 · 예상 DPS 대기';$('island-dps').textContent='—';$('island-detail').textContent='저장 덱을 계산하면 예상 DPS가 표시됩니다.';$('analyze').disabled=false;$('stop').disabled=true;status(message);}
function job(input,id){return new Promise((resolve,reject)=>{pendingReject=reject;clearTimeout(timer);timer=setTimeout(()=>{worker?.terminate();worker=null;pendingReject=null;reject(Error('계산 시간이 30초를 초과했습니다.'));},30000);worker.onmessage=({data})=>{if(data.id!==id)return;clearTimeout(timer);pendingReject=null;data.error?reject(Error(data.error)):resolve(data);};worker.onerror=()=>{clearTimeout(timer);pendingReject=null;reject(Error('계산 작업을 실행하지 못했습니다.'));};worker.postMessage({...input,id,kind:'calculate',omenGrowth:false,fullProgress:false});});}
$('analyze').onclick=async()=>{stop('저장 덱을 읽는 중…');const token=runToken;try{const saved=JSON.parse(localStorage.getItem('coop-lab-board-v2')||'null');if(!saved?.cells?.length||!saved.you?.perDemon||!saved.partner?.perDemon)throw Error('저장 덱이 없습니다. 배치 화면에서 먼저 저장하세요.');const input=CoopPresets.withDefaults(saved,CoopEngine,CoopData);$('analyze').disabled=true;$('stop').disabled=false;worker=new Worker('/mobile-assistant-worker.js');status('이 기기에서 제단 적용 전후를 계산합니다…');const baseline=structuredClone(input);baseline.you.altar={};baseline.partner.altar={};const current=await job(input,1);if(token!==runToken)return;const base=await job(baseline,2);if(token!==runToken)return;worker.terminate();worker=null;const total=current.units.reduce((sum,u)=>sum+u.dps,0);const intro=document.createElement('p');intro.textContent='예상 실전 평균 DPS '+fmt(current.actual)+' · 제단 미적용 대비 '+(base.actual>0?((current.actual/base.actual-1)*100).toFixed(2)+'%':'비교 불가');$('results').append(intro);const note=document.createElement('p');note.textContent='저장 덱·대상 기준 추정치입니다. 아래 수치는 캐릭터별 이론 DPS 및 그 합계 대비 비중이며 실측 딜량·승률이 아닙니다. 양쪽 진영의 제단 전체를 제외한 조건과 비교합니다.';$('results').append(note);const table=document.createElement('table');const head=document.createElement('tr');for(const label of ['캐릭터','이론 DPS','비중']){const th=document.createElement('th');th.textContent=label;head.append(th);}table.append(head);for(const u of [...current.units].sort((a,b)=>b.dps-a.dps)){const row=document.createElement('tr'),name=CoopData.DEMON_BY_SLUG.get(u.slug)?.name||u.slug;for(const value of [dict[name]||name,fmt(u.dps),total>0?(u.dps/total*100).toFixed(1)+'%':'—']){const td=document.createElement('td');td.textContent=value;row.append(td);}table.append(row);}$('results').append(table);$('overlay').textContent='예상 DPS '+fmt(current.actual)+' · 실측 아님';$('island-dps').textContent=compact(current.actual);$('island-detail').textContent='저장 덱 기준 예상 DPS '+fmt(current.actual)+' · 기기 내 계산 결과';status('로컬 계산 완료 · 서버 요청 및 결과 저장 없음');}catch(e){if(token===runToken)status(e.message);}finally{if(token===runToken){clearTimeout(timer);worker?.terminate();worker=null;$('analyze').disabled=false;}}};
$('stop').onclick=()=>stop();$('clear').onclick=clearImage;
$('capture').onchange=async()=>{const file=$('capture').files[0];clearImage();const token=imageToken;if(!file)return;try{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8*1024*1024)throw Error('8MB 이하 PNG·JPEG·WebP만 선택하세요.');const bitmap=await createImageBitmap(file);const valid=bitmap.width*bitmap.height<=16000000;bitmap.close();if(token!==imageToken)return;if(!valid)throw Error('1,600만 픽셀 이하 이미지를 선택하세요.');url=URL.createObjectURL(file);$('preview').src=url;$('preview').hidden=false;}catch(e){if(token===imageToken)status(e.message);}};
let touches=0;$('game').onpointerdown=()=>{$('touches').textContent=++touches;};$('game').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('touches').textContent=++touches;}};$('position').onchange=()=>$('overlay').classList.toggle('bottom',$('position').value==='bottom');
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop('화면을 벗어나 캡처와 결과를 비웠습니다.');});window.addEventListener('pagehide',()=>stop());window.addEventListener('stack-lab:workspace-away',()=>stop());fetch('/ko.json').then(r=>r.json()).then(d=>dict=d).catch(()=>{});
})();